      en: 'This draft is only as accurate as your regular, complete tracking in the app. It is not tax advice.',
      kk: 'Жоба қосымшадағы есебіңіз қаншалықты тұрақты әрі толық болса, соншалықты дәл. Бұл салықтық кеңес емес.',
      de: 'Der Entwurf ist nur so genau wie Ihre regelmäßige, vollständige Erfassung in der App. Keine Steuerberatung.',
