      zh: '草稿的准确程度取决于您在应用中记录的规律性和完整性。这不是税务建议。',
      pl: 'Wersja robocza jest tak dokładna, jak regularna i pełna jest Twoja ewidencja w aplikacji. To nie jest doradztwo podatkowe.',
      it: 'La bozza è accurata quanto la regolarità e completezza delle tue registrazioni nell’app. Non è una consulenza fiscale.',
      sk: 'Návrh je presný len natoľko, nakoľko pravidelne a úplne vediete evidenciu v aplikácii. Nejde o daňové poradenstvo.',
      ja: 'この下書きの正確さは、アプリでの定期的かつ漏れのない記録次第です。税務アドバイスではありません。',
