      hi: 'यह मसौदा उतना ही सटीक है जितना ऐप में आपका नियमित और पूर्ण रिकॉर्ड। यह कर सलाह नहीं है।',
      nl: 'Dit concept is zo nauwkeurig als je regelmatige, volledige registratie in de app. Het is geen belastingadvies.',
