      vi: 'Bản nháp chỉ chính xác khi bạn ghi chép đều đặn và đầy đủ trong ứng dụng. Đây không phải tư vấn thuế.',
      id: 'Draf ini hanya seakurat pencatatan rutin dan lengkap Anda di aplikasi. Ini bukan nasihat pajak.',
      da: 'Dette udkast er kun så nøjagtigt som din regelmæssige, fuldstændige registrering i appen. Det er ikke skatterådgivning.',
