      vi: 'Ngoại tệ được quy đổi theo tỷ giá trung bình NBP của ngày làm việc cuối cùng trước ngày giao dịch (Điều 11a Luật PIT).',
      id: 'Mata uang asing dikonversi dengan kurs rata-rata NBP hari kerja terakhir sebelum tanggal transaksi (pasal 11a UU PIT).',
      da: "Fremmed valuta omregnes til NBP's gennemsnitskurs på den sidste bankdag før transaktionsdatoen (art. 11a i PIT-loven).",
      nb: 'Utenlandsk valuta omregnes til NBPs gjennomsnittskurs på siste bankdag før transaksjonsdatoen (art. 11a i PIT-loven).',
