      fi: 'Ulkomaan valuutta muunnetaan NBP:n keskikurssilla tapahtumapäivää edeltävältä viimeiseltä pankkipäivältä (PIT-lain 11a art.).',
      is: 'Erlendri mynt er umreiknað á meðalgengi NBP síðasta bankadag fyrir færsludaginn (11a. gr. PIT-laganna).',
